import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.CsFjlSKj.js";const k=JSON.parse('{"title":"5. Networking Basics","description":"","frontmatter":{},"headers":[],"relativePath":"linux/networking.md","filePath":"linux/networking.md"}'),t={name:"linux/networking.md"};function l(p,s,h,o,r,d){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="_5-networking-basics" tabindex="-1">5. Networking Basics <a class="header-anchor" href="#_5-networking-basics" aria-label="Permalink to &quot;5. Networking Basics&quot;">​</a></h1><p>Understanding how a Linux system connects to networks, resolves hostnames, and protects itself is a fundamental skill.</p><h2 id="network-interfaces-and-ip-addresses" tabindex="-1">Network Interfaces and IP Addresses <a class="header-anchor" href="#network-interfaces-and-ip-addresses" aria-label="Permalink to &quot;Network Interfaces and IP Addresses&quot;">​</a></h2><p>A Linux machine connects to networks via interfaces (e.g., <code>eth0</code> for wired ethernet, <code>wlan0</code> for wireless, or <code>lo</code> for the local loopback).</p><h3 id="viewing-ip-addresses" tabindex="-1">Viewing IP Addresses <a class="header-anchor" href="#viewing-ip-addresses" aria-label="Permalink to &quot;Viewing IP Addresses&quot;">​</a></h3><p>Use the <code>ip</code> command (which replaces the deprecated <code>ifconfig</code>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show IP addresses for all interfaces</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show routing table (Default Gateway)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span></span></code></pre></div><h2 id="dns-resolution" tabindex="-1">DNS Resolution <a class="header-anchor" href="#dns-resolution" aria-label="Permalink to &quot;DNS Resolution&quot;">​</a></h2><p>When you ping <code>google.com</code>, Linux needs to convert that hostname into an IP address.</p><ol><li><strong><code>/etc/hosts</code></strong>: The system checks this file first. You can manually map IPs to hostnames here to override public DNS (useful for local development).<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Example /etc/hosts entry</span></span>
<span class="line"><span>192.168.1.50   my-database-server</span></span></code></pre></div></li><li><strong><code>/etc/resolv.conf</code></strong>: If the hostname isn&#39;t in <code>/etc/hosts</code>, the system queries the nameservers listed in this file.<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Example /etc/resolv.conf</span></span>
<span class="line"><span>nameserver 8.8.8.8</span></span>
<span class="line"><span>nameserver 1.1.1.1</span></span></code></pre></div></li></ol><h2 id="firewalls" tabindex="-1">Firewalls <a class="header-anchor" href="#firewalls" aria-label="Permalink to &quot;Firewalls&quot;">​</a></h2><p>By default, the Linux Kernel has a built-in firewall called <code>Netfilter</code>. Direct configuration is extremely complex, so user-space frontend tools are used instead.</p><h3 id="ufw-uncomplicated-firewall-on-ubuntu" tabindex="-1">UFW (Uncomplicated Firewall) on Ubuntu <a class="header-anchor" href="#ufw-uncomplicated-firewall-on-ubuntu" aria-label="Permalink to &quot;UFW (Uncomplicated Firewall) on Ubuntu&quot;">​</a></h3><p>UFW provides a simple CLI to manage rules.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable the firewall</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Allow SSH traffic (port 22)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Allow HTTP and HTTPS traffic</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 443/tcp</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check current firewall status and rules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><h3 id="firewalld-on-centos-rhel" tabindex="-1">Firewalld on CentOS/RHEL <a class="header-anchor" href="#firewalld-on-centos-rhel" aria-label="Permalink to &quot;Firewalld on CentOS/RHEL&quot;">​</a></h3><p>Firewalld uses the concept of &quot;zones&quot;.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Allow HTTP traffic permanently</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --permanent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add-service=http</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reload the firewall to apply the changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-cmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reload</span></span></code></pre></div>`,18)])])}const u=a(t,[["render",l]]);export{k as __pageData,u as default};
